import cpmpy as cp
import json

# Input data
n_boats = 5
n_periods = 4
capacity = [6, 8, 12, 12, 12]
crew_size = [2, 2, 2, 2, 4]

# Model definition
model = cp.Model()

# Decision Variables
is_host = cp.boolvar(shape=n_boats, name="is_host")  # 1 if boat is a host, 0 otherwise
visits = cp.intvar(0, n_boats-1, shape=(n_boats, n_periods), name="visits")  # visits[b][p] is the host visited by boat b in period p

# Constraints
# A boat cannot visit itself (hosts stay on their own boat)
for b in range(n_boats):
    for p in range(n_periods):
        model += (visits[b,p] != b).implies(~is_host[b])  # if a boat visits another, it's not a host

# Host boats stay on their own boat in all periods
for b in range(n_boats):
    for p in range(n_periods):
        model += is_host[b].implies(visits[b,p] == b)

# Capacity constraints: for each host and period, sum of guest crews + host crew <= capacity
for h in range(n_boats):
    for p in range(n_periods):
        # Sum of crew sizes of boats visiting h in period p
        guest_crews = cp.sum([(visits[b,p] == h) * crew_size[b] for b in range(n_boats) if b != h])
        model += (guest_crews + crew_size[h] <= capacity[h]).implies(is_host[h])  # only enforce if h is a host

# A guest boat cannot revisit a host
for b in range(n_boats):
    for h in range(n_boats):
        if b != h:
            model += cp.sum([visits[b,p] == h for p in range(n_periods)]) <= 1

# Guest crews cannot meet more than once (no two guest boats visit the same set of hosts)
for b1 in range(n_boats):
    for b2 in range(b1+1, n_boats):
        if b1 != b2:
            # Count the number of periods where b1 and b2 visit the same host
            same_host_periods = cp.sum([visits[b1,p] == visits[b2,p] for p in range(n_periods)])
            model += same_host_periods <= 1

# Objective: minimize the number of host boats
model.minimize(cp.sum(is_host))

# Solve and print
if model.solve():
    solution = {
        'visits': visits.value().tolist(),
        'is_host': [int(v) for v in is_host.value()]
    }
    print(json.dumps(solution, indent=4))
else:
    print("No solution found.")
